@props(['eventos'=>[], 'identificador'=>'horario-personal', 'selectorPeriodo'=>true, 'bloques'=>[], 'editable'=>false, 'mensajeVacio'=>'Las cargas asignadas se conservan. Puedes consultarlas debajo del horario.'])
