    <div class="ui-horario-filtro mt-4">@if($selectorPeriodo)<x-selector-institucional enlace="plantilla" :identificador="$identificador.'-plantilla'" etiqueta="Horario y período" :opciones="collect($eventos)->unique('plantilla_id')->map(fn($evento)=>['valor'=>$evento['plantilla_id'],'etiqueta'=>$evento['plantilla'].($evento['aplicada']?' · Aplicado':'')])->values()->all()" />@endif<x-selector-institucional enlace="turno" :identificador="$identificador.'-turno'" etiqueta="Turno" :opciones="array_merge([['valor'=>'','etiqueta'=>'Todos los turnos']],collect($eventos)->pluck('turno')->unique()->map(fn($nombre)=>['valor'=>$nombre,'etiqueta'=>$nombre])->values()->all())" /><p class="ui-muted text-xs" x-text="filtrados.length+' bloques registrados'+(comprimir?' · '+visibles.length+' sesiones':'')"></p></div>
