    <div class="ui-horario-semana mt-4" x-show="vista==='semana'&&!comprimir&&(filtrados.length||(editable&&bloques.length))"><table><caption class="sr-only">Horario semanal de clases registradas</caption><thead><tr><th scope="col">Bloque</th><template x-for="dia in dias" :key="dia"><th scope="col" x-text="dia"></th></template></tr></thead><tbody><template x-for="fila in filas" :key="fila.clave"><tr><th scope="row"><strong x-text="fila.inicio"></strong><span x-text="fila.fin"></span></th><template x-for="dia in dias" :key="fila.clave+dia"><td><template x-for="clase in celda(fila,dia)" :key="clase.id"><button type="button" class="ui-horario-clase" :class="clase.tipo==='Materia curricular'?'ui-horario-materia':'ui-horario-tecnica'" x-on:click="seleccionada=clase" :aria-pressed="seleccionada?.id===clase.id" :aria-label="clase.nombre+', '+dia+', '+clase.inicio+' a '+clase.fin+', '+clase.curso+' '+clase.paralelo"><strong x-text="clase.nombre"></strong><span x-text="clase.curso+' · '+clase.paralelo"></span><small x-show="clase.coincide"><i class="ph-duotone ph-warning" aria-hidden="true"></i>Bloques simultáneos</small></button></template><button type="button" class="ui-horario-agregar" x-show="editable&&fila.codigo&&!celda(fila,dia).length" x-on:click="abrirCelda(fila,dia)" :aria-label="'Agregar clase el '+dia+', '+fila.inicio+' a '+fila.fin"><i class="ph-duotone ph-plus-circle" aria-hidden="true"></i><span>Agregar clase</span></button><span class="ui-horario-sin-clase" x-show="!celda(fila,dia).length&&(!editable||!fila.codigo)">—</span></td></template></tr></template></tbody></table></div>
